package app.onklav.home

import android.content.Context
import android.text.*
import android.text.style.*
import com.sun.mail.imap.IMAPFolder
import com.sun.mail.imap.IMAPMessage
import com.sun.mail.smtp.SMTPTransport
import kotlinx.coroutines.*
import org.json.JSONObject
import java.io.*
import java.util.*
import javax.activation.*
import javax.mail.*
import javax.mail.Message as EmailMessage
import javax.mail.internet.*
import javax.mail.search.*

internal object MailMime{
 fun addresses(raw:String):Array<InternetAddress>{require(raw.length<=16000&&raw.none{it=='\r'||it=='\n'}){"Invalid email address"};if(raw.isBlank())return emptyArray();return InternetAddress.parse(raw.replace(';',','),true).also{require(it.size<=100){"Use up to 100 recipients"};it.forEach{a->a.validate();require(a.address.contains('@')&&!a.isGroup){"Enter a complete email address"}}}}
 fun readBounded(input:InputStream,max:Int):ByteArray{val out=ByteArrayOutputStream();val b=ByteArray(16384);while(true){val n=input.read(b);if(n<0)break;require(out.size()+n<=max){"Message is too large to display. Save the original email instead."};out.write(b,0,n)};return out.toByteArray()}
 fun display(html:String):SpannableStringBuilder{val clean=html.replace(Regex("(?is)<(script|style|head|iframe|object|form)\\b[^>]*>.*?</\\1\\s*>"),"");val text=SpannableStringBuilder(Html.fromHtml(clean,Html.FROM_HTML_MODE_COMPACT));text.getSpans(0,text.length,Any::class.java).filter{it is android.text.style.ImageSpan||it is ForegroundColorSpan||it is BackgroundColorSpan||it is AbsoluteSizeSpan||it is RelativeSizeSpan||it is URLSpan&&runCatching{safeLink(it.url)}.isFailure}.forEach{text.removeSpan(it)};return text}
 fun body(part:Part):MailBody{var plain="";var html="";var total=0;val files=mutableListOf<MailAttachment>();var parts=0
  fun visit(p:Part,path:String,depth:Int){require(depth<=16&&++parts<=500){"Message structure is too complex"};val name=p.fileName?.let{runCatching{MimeUtility.decodeText(it)}.getOrDefault(it)}?.take(240);val type=p.contentType.substringBefore(';').lowercase();val attachment=p.disposition.equals(Part.ATTACHMENT,true)||!name.isNullOrBlank()||type !in listOf("text/plain","text/html")&&!p.isMimeType("multipart/*")
   if(attachment){files.add(MailAttachment(path,name?:if(p.isMimeType("message/rfc822"))"Attached email.eml" else"Attachment",type,p.size.toLong()));return}
   when{p.isMimeType("multipart/*")->{val m=p.content as Multipart;require(m.count<=500);for(i in 0 until m.count)visit(m.getBodyPart(i),if(path.isEmpty())"$i" else"$path.$i",depth+1)};p.isMimeType("text/plain")||p.isMimeType("text/html")->{val bytes=p.inputStream.use{readBounded(it,1_000_000-total)};total+=bytes.size;val charset=runCatching{java.nio.charset.Charset.forName(ContentType(p.contentType).getParameter("charset")?:"UTF-8")}.getOrDefault(Charsets.UTF_8);val text=String(bytes,charset).replace("\r\n","\n").replace('\r','\n');if(p.isMimeType("text/plain"))plain+=text+"\n" else html+=text}}
  };visit(part,"",0);if(plain.isBlank()&&html.isNotBlank())plain=display(html).toString();return MailBody(plain.trimEnd(),html,files)
 }
 fun part(root:Part,path:String):Part{if(path.isEmpty())return root;var p=root;path.split('.').forEach{index->require(index.matches(Regex("[0-9]{1,3}")));val m=p.content as? Multipart?:error("Attachment is unavailable");val n=index.toInt();require(n in 0 until m.count);p=m.getBodyPart(n)};return p}
 fun outgoing(session:Session,a:MailAccount,d:MailDraft,file:(String)->DataSource):MimeMessage{
  val to=addresses(d.to);val cc=addresses(d.cc);val bcc=addresses(d.bcc);require(to.size+cc.size+bcc.size in 1..100){"Add at least one recipient"};require(d.subject.length<=998&&d.subject.none{it=='\r'||it=='\n'}){"Subject is too long"};require(d.doc.text.length<=500000);val msg=MimeMessage(session);msg.setFrom(InternetAddress(a.email,a.name,"UTF-8"));msg.setRecipients(EmailMessage.RecipientType.TO,to);msg.setRecipients(EmailMessage.RecipientType.CC,cc);msg.setRecipients(EmailMessage.RecipientType.BCC,bcc);msg.setSubject(d.subject,"UTF-8");msg.sentDate=Date();if(d.replyId.isNotBlank()&&d.replyId.length<=998&&d.replyId.none{it=='\r'||it=='\n'}){msg.setHeader("In-Reply-To",d.replyId);msg.setHeader("References",d.replyId)}
  val alt=MimeMultipart("alternative");alt.addBodyPart(MimeBodyPart().apply{setText(d.doc.text,"UTF-8")});alt.addBodyPart(MimeBodyPart().apply{setContent(d.doc.html(),"text/html; charset=UTF-8")});val mixed=MimeMultipart("mixed");mixed.addBodyPart(MimeBodyPart().apply{setContent(alt)})
  var size=0L;d.files.forEach{f->val source=file(f.part);size+=f.size;require(size<=25_000_000){"Attachments exceed 25 MB. Remove one or share a link."};mixed.addBodyPart(MimeBodyPart().apply{dataHandler=DataHandler(source);fileName=f.name;disposition=Part.ATTACHMENT})};msg.setContent(mixed);msg.saveChanges();return msg
 }
 fun error(e:Throwable):String{val chain=generateSequence(e){it.cause}.take(10).toList();return when{chain.any{it is AuthenticationFailedException}->"Sign-in was rejected. Reconnect the account or check its app password.";chain.any{it is javax.net.ssl.SSLException}->"A secure connection could not be verified. Check the server settings.";chain.any{it is java.net.UnknownHostException}->"Mail server not found. Check the server address and your connection.";chain.any{it is java.net.SocketTimeoutException}->"The mail server took too long to respond. Try again.";chain.any{it is FolderNotFoundException}->"This folder is no longer available. Refresh the folder list.";e is IllegalArgumentException||e is IllegalStateException->e.message?.take(240)?:"The operation could not complete.";else->"Couldn’t connect to the mail server. Check your connection and try again."}}
}
internal data class MailPage(val headers:List<MailHeader>,val more:Boolean,val validity:Long)
internal class MailProtocol(private val c:Context,private val disk:MailDisk,private val verify:()->Unit){
 private fun session():Session{val p=Properties();for(proto in listOf("imaps","smtp","smtps")){p["mail.$proto.connectiontimeout"]="12000";p["mail.$proto.timeout"]="25000";p["mail.$proto.writetimeout"]="25000";p["mail.$proto.ssl.checkserveridentity"]="true";p["mail.$proto.ssl.protocols"]="TLSv1.2 TLSv1.3"};p["mail.imaps.peek"]="true";p["mail.imaps.fetchsize"]="65536";p["mail.imaps.partialfetch"]="true";p["mail.smtp.starttls.enable"]="true";p["mail.smtp.starttls.required"]="true";p["mail.smtp.auth"]="true";p["mail.smtps.auth"]="true";p["mail.mime.encodefilename"]="true";p["mail.mime.decodefilename"]="true";return Session.getInstance(p)}
 private suspend fun secret(a:MailAccount,smtp:Boolean=false):String{verify();return run{val j=disk.read("secret-${a.id}")?:error("Reconnect this account");j.optString(if(smtp)"smtpPassword" else"password").ifEmpty{j.getString("password")}}}
 private suspend fun <T> connection(a:MailAccount,block:suspend(Store)->T):T=withContext(Dispatchers.IO){coroutineScope{verify();a.validate();val store=session().getStore("imaps");val watcher=launch(Dispatchers.IO,start=CoroutineStart.UNDISPATCHED){try{awaitCancellation()}finally{runCatching{store.close()}}};try{val password=secret(a);verify();store.connect(a.imap,a.imapPort,a.user,password);verify();block(store)}finally{watcher.cancel();runCatching{store.close()}}}}
 suspend fun test(a:MailAccount){connection(a){s->require(s.getFolder("INBOX").exists()){ "Inbox not found" }};withContext(Dispatchers.IO){val proto=if(a.smtpTls)"smtp" else"smtps";val t=session().getTransport(proto);try{t.connect(a.smtp,a.smtpPort,a.smtpUser,secret(a,true));verify()}finally{runCatching{t.close()}}}}
 suspend fun folders(a:MailAccount):List<MailFolder> =connection(a){s->s.defaultFolder.list("*").take(500).map{f->val attrs=(f as? IMAPFolder)?.attributes.orEmpty();val role=when{attrs.any{it.equals("\\Sent",true)}->"sent";attrs.any{it.equals("\\Trash",true)}->"trash";attrs.any{it.equals("\\Archive",true)}->"archive";attrs.any{it.equals("\\Junk",true)}->"junk";attrs.any{it.equals("\\Drafts",true)}->"drafts";f.fullName.equals("INBOX",true)->"inbox";else->when(f.name.lowercase()){ "sent","sent items","sent messages"->"sent";"trash","deleted items","deleted messages"->"trash";"archive","archives"->"archive";"junk","spam","junk email"->"junk";"drafts"->"drafts";else->""}};MailFolder(f.fullName,f.fullName,role,f.type and Folder.HOLDS_MESSAGES!=0)}.sortedWith(compareBy<MailFolder>{if(it.role=="inbox")0 else 1}.thenBy{it.path.lowercase()})}
 private fun header(a:MailAccount,f:IMAPFolder,m:EmailMessage)=MailHeader(a.id,f.fullName,f.uidValidity,f.getUID(m),m.from.orEmpty().joinToString(", "){MimeUtility.decodeText(it.toString())}.take(1000),m.getRecipients(EmailMessage.RecipientType.TO).orEmpty().joinToString(", "){it.toString()}.take(1000),m.subject?.take(1000).orEmpty(),(m.receivedDate?:m.sentDate)?.time?:0,m.isSet(Flags.Flag.SEEN),m.isSet(Flags.Flag.FLAGGED),m.contentType.startsWith("multipart/mixed",true),(m as? IMAPMessage)?.messageID.orEmpty().take(998),m.replyTo.orEmpty().joinToString(", "){it.toString()}.take(1000),m.getRecipients(EmailMessage.RecipientType.CC).orEmpty().joinToString(", "){it.toString()}.take(1000),(mailMessageIds(m.getHeader("References").orEmpty().joinToString(" "))+mailMessageIds(m.getHeader("In-Reply-To").orEmpty().joinToString(" "))).distinct().take(20))
 suspend fun page(a:MailAccount,path:String,limit:Int=50,before:Long?=null,query:String=""):MailPage=connection(a){s->val f=s.getFolder(path) as IMAPFolder;f.open(Folder.READ_ONLY);try{val messages=if(query.isNotBlank()){require(query.length<=200);val term=OrTerm(arrayOf(SubjectTerm(query),FromStringTerm(query),RecipientStringTerm(EmailMessage.RecipientType.TO,query)));f.search(term).filter{before==null||f.getUID(it)<before}.takeLast(limit).toTypedArray()}else if(before!=null){val seq=f.getMessageByUID(before)?.messageNumber;if(seq!=null){if(seq<=1)emptyArray()else f.getMessages((seq-limit).coerceAtLeast(1),seq-1)}else f.getMessagesByUID(1,before-1).filterNotNull().takeLast(limit).toTypedArray()}else{val count=f.messageCount;if(count==0)emptyArray()else f.getMessages((count-limit+1).coerceAtLeast(1),count)};val profile=FetchProfile().apply{add(FetchProfile.Item.ENVELOPE);add(FetchProfile.Item.FLAGS);add(FetchProfile.Item.CONTENT_INFO);add(UIDFolder.FetchProfileItem.UID);add("References");add("In-Reply-To")};if(messages.isNotEmpty())f.fetch(messages,profile);verify();MailPage(messages.filterNot{it.isExpunged}.map{header(a,f,it)}.sortedByDescending{it.date},messages.size>=limit,f.uidValidity)}finally{f.close(false)}}
 private suspend fun <T> message(a:MailAccount,h:MailHeader,write:Boolean=false,block:suspend(IMAPFolder,EmailMessage)->T):T=connection(a){s->val f=s.getFolder(h.folder) as IMAPFolder;f.open(if(write)Folder.READ_WRITE else Folder.READ_ONLY);try{check(f.uidValidity==h.validity){"This folder changed on the server. Refresh and reopen the message."};val m=f.getMessageByUID(h.uid)?:error("This message moved or was deleted. Refresh the folder.");verify();block(f,m)}finally{f.close(false)}}
 suspend fun body(a:MailAccount,h:MailHeader)=message(a,h){_,m->MailMime.body(m).also{verify()}}
 suspend fun flag(a:MailAccount,h:MailHeader,star:Boolean?=null,seen:Boolean?=null)=message(a,h,true){_,m->star?.let{m.setFlag(Flags.Flag.FLAGGED,it)};seen?.let{m.setFlag(Flags.Flag.SEEN,it)};verify();Unit}
 suspend fun move(a:MailAccount,h:MailHeader,destination:String)=message(a,h,true){f,m->require(destination!=h.folder){"Already in this folder"};val target=f.store.getFolder(destination);require(target.exists()&&target.type and Folder.HOLDS_MESSAGES!=0){"Choose a mail folder"};check((f.store as com.sun.mail.imap.IMAPStore).hasCapability("MOVE")){"This server does not support safe Move. Use Copy, then delete in your provider’s mail app."};f.moveMessages(arrayOf(m),target);verify()}
 suspend fun copy(a:MailAccount,h:MailHeader,destination:String)=message(a,h){f,m->val target=f.store.getFolder(destination);require(target.exists());f.copyMessages(arrayOf(m),target);verify()}
 suspend fun delete(a:MailAccount,h:MailHeader)=message(a,h,true){f,m->check((f.store as com.sun.mail.imap.IMAPStore).hasCapability("UIDPLUS")){"This server does not support safe permanent deletion. Use its mail app."};m.setFlag(Flags.Flag.DELETED,true);f.expunge(arrayOf(m));verify();Unit}
 suspend fun folder(a:MailAccount,path:String,action:String,newName:String="")=connection(a){s->require(path.isNotBlank()&&path.length<=500&&path.none{it=='\r'||it=='\n'});val f=s.getFolder(path);if(action!="create"){val attrs=(f as? IMAPFolder)?.attributes.orEmpty();require(!path.equals("INBOX",true)&&attrs.none{it.lowercase() in setOf("\\sent","\\trash","\\archive","\\junk","\\drafts","\\all","\\flagged")}&&f.name.lowercase() !in setOf("sent","sent items","sent messages","trash","deleted items","deleted messages","archive","archives","junk","spam","junk email","drafts")){"System folders cannot be changed here"}};when(action){"create"->check(f.create(Folder.HOLDS_MESSAGES)){"Couldn’t create folder"};"rename"->{require(newName.isNotBlank()&&newName.length<=500&&newName.none{it=='\r'||it=='\n'});check(f.renameTo(s.getFolder(newName))){"Couldn’t rename folder"}};"delete"->{f.open(Folder.READ_ONLY);val count=try{f.messageCount}finally{f.close(false)};require(count==0){"Move the messages out before deleting this folder"};check(f.delete(false)){"Folder is not empty or could not be deleted"}}};verify();Unit}
 suspend fun download(a:MailAccount,h:MailHeader,p:MailAttachment,out:OutputStream,progress:(Long,Long)->Unit)=message(a,h){_,m->val part=MailMime.part(m,p.part);part.inputStream.use{input->val b=ByteArray(65536);var n=0L;while(true){currentCoroutineContext().ensureActive();verify();val read=input.read(b);if(read<0)break;n+=read;out.write(b,0,read);progress(n,part.size.toLong())}};Unit}
 suspend fun original(a:MailAccount,h:MailHeader,out:OutputStream)=message(a,h){_,m->verify();m.writeTo(out);verify()}
 suspend fun send(a:MailAccount,d:MailDraft,files:(String)->DataSource,phase:(String)->Unit):String=withContext(Dispatchers.IO){verify();val session=session();val msg=MailMime.outgoing(session,a,d,files);val recipients=msg.allRecipients;msg.removeHeader("Bcc");msg.saveChanges();val t=session.getTransport(if(a.smtpTls)"smtp" else"smtps") as SMTPTransport;var submitting=false
  try{val password=secret(a,true);verify();t.connect(a.smtp,a.smtpPort,a.smtpUser,password);verify();phase("sending");submitting=true;t.sendMessage(msg,recipients);phase("sent")}catch(e:Exception){phase(if(submitting)"uncertain" else"draft");if(submitting)throw IllegalStateException("Delivery is unconfirmed. Check Sent before sending again; some recipients may have received it.");throw e}finally{runCatching{t.close()}}
  // SMTP acceptance is final even if saving the Sent copy fails. Never offer an automatic resend.
  try{val sent=disk.folders(a.id).firstOrNull{it.role=="sent"};if(sent!=null&&a.provider!="Gmail")connection(a){s->val f=s.getFolder(sent.path);msg.setFlag(Flags.Flag.SEEN,true);f.appendMessages(arrayOf(msg));verify()};"Sent"}catch(e:Exception){"Sent · couldn’t save a server copy. The local sent copy is in Drafts & sent."}
 }
}
